#[derive(Default, PartialEq, Debug, Clone)]
pub struct ReflectionSchema {
    advanced_features: ReflectionAdvancedFeatures,
    enums: Vec<ReflectionEnum>,
    /// All the files used in this compilation. Files are relative to where
    /// flatc was invoked.
    fbs_files: Option<Vec<ReflectionSchemaFile>>,
    file_ext: Option<String>,
    file_ident: Option<String>,
    objects: Vec<ReflectionObject>,
    root_table: Option<ReflectionObject>,
    services: Option<Vec<ReflectionService>>,
}

impl ReflectionSchema {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsReflectionSchema<'a>> {
        use crate::types::generated::reflection_generated::reflection::SchemaBuilder as FbsReflectionSchemaBuilder;

        let mut enums_offsets = Vec::with_capacity(self.enums.len());
        for val in self.enums.iter() {
            let offset = val.serialize_to(builder);
            enums_offsets.push(offset);
        }
        let enums_offset = builder.create_vector(&enums_offsets);
        let fbs_files_offset = self.fbs_files.as_ref().map(|v| {
            let mut fbs_files_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                fbs_files_offsets.push(offset);
            }
            let fbs_files_offset = builder.create_vector(&fbs_files_offsets);
            fbs_files_offset
        });
        let file_ext_offset = self.file_ext.as_ref().map(|s| builder.create_string(s));
        let file_ident_offset = self.file_ident.as_ref().map(|s| builder.create_string(s));
        let mut objects_offsets = Vec::with_capacity(self.objects.len());
        for val in self.objects.iter() {
            let offset = val.serialize_to(builder);
            objects_offsets.push(offset);
        }
        let objects_offset = builder.create_vector(&objects_offsets);
        let root_table_offset = self.root_table.as_ref().map(|o| o.serialize_to(builder));
        let services_offset = self.services.as_ref().map(|v| {
            let mut services_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                services_offsets.push(offset);
            }
            let services_offset = builder.create_vector(&services_offsets);
            services_offset
        });

        let mut bldr = FbsReflectionSchemaBuilder::new(builder);
        bldr.add_advanced_features(FbsReflectionAdvancedFeatures::from(self.advanced_features));
        bldr.add_enums(enums_offset);
        if let Some(offset) = fbs_files_offset {
            bldr.add_fbs_files(offset);
        }
        if let Some(offset) = file_ext_offset {
            bldr.add_file_ext(offset);
        }
        if let Some(offset) = file_ident_offset {
            bldr.add_file_ident(offset);
        }
        bldr.add_objects(objects_offset);
        if let Some(offset) = root_table_offset {
            bldr.add_root_table(offset);
        }
        if let Some(offset) = services_offset {
            bldr.add_services(offset);
        }
        bldr.finish()
    }
}

impl From<FbsReflectionSchema<'_>> for ReflectionSchema {
    fn from(fbs: FbsReflectionSchema<'_>) -> Self {
        let advanced_features = ReflectionAdvancedFeatures::from(fbs.advanced_features());
        let mut enums = Vec::new();
        for elem in fbs.enums() {
            enums.push(elem.into());
        }

        let fbs_files = if let Some(val) = fbs.fbs_files() {
            let mut fbs_files = Vec::new();
            for elem in val {
                fbs_files.push(elem.into());
            }

            Some(fbs_files)
        } else {
            None
        };

        let file_ext = fbs.file_ext().map(ToOwned::to_owned);
        let file_ident = fbs.file_ident().map(ToOwned::to_owned);
        let mut objects = Vec::new();
        for elem in fbs.objects() {
            objects.push(elem.into());
        }

        let root_table = fbs.root_table().map(ReflectionObject::from);
        let services = if let Some(val) = fbs.services() {
            let mut services = Vec::new();
            for elem in val {
                services.push(elem.into());
            }

            Some(services)
        } else {
            None
        };

        Self {
            advanced_features,
            enums,
            fbs_files,
            file_ext,
            file_ident,
            objects,
            root_table,
            services,
        }
    }
}

impl TryFrom<&[u8]> for ReflectionSchema {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsReflectionSchema>(bytes)?;
        Ok(Self::from(fbs))
    }
}

